(function(window){var DomainCheck=function(obj,loading,results,search,button)
{if(!$(document).find(loading).length||!$(document).find(results).length||!$(document).find(search).length||!$(document).find(button).length){return;}
this.obj=obj;this.loading=loading;this.results=results;this.search=search;this.button=button;this.lastSelection='';var that=this;$(document).on('click',this.button,function(e){e.preventDefault();if(!$(document).find(that.search).val().length){return;}
if($(document).find(that.search).val()===that.lastSelection){return;}
$(document).find(that.loading).show();$.ajax({type:'GET',url:'/ajax.php?mod=Beheer&action=checkDomain',data:{domain:$(document).find(that.search).val(),obj:that.obj,},success:function(result)
{result=$.parseJSON(result);$(document).find(that.results).html(result.html);$(document).find(that.results).show();$(document).find(that.loading).hide();}});});this.select=function(event,domain)
{event.preventDefault();$(document).find(this.search).val(domain);$(document).find(this.results).hide();this.lastSelection=domain;this.updateDomain(domain);};this.updateDomain=function(domain)
{$('input[name="Domeinnaam"]').val(domain);$(".contactbanner-form-holder:hidden").slideToggle();$(".toggle-helpdesk-form").addClass("active");$('html, body').animate({scrollTop:$('#contactform').offset().top},'slow');};};window.DomainCheck=DomainCheck;})(window);;